  "upload.rerequest.closing_moved": { key: "upload.rerequest.closing_moved", kind: "UploadCard", text: "Closing moved to {{date}}, so we need a {{document}} from the last {{n}} days.", notes: "32.5 §2.3: the replacement request 22.1's freshness sweep opens at expiry (`SM_DOC_EXPIRY_WARN_14`, `FNMA_B1_1_03_CREDIT_DOCS_4M`); the date is the owning process's scheduled note date.", extras: [], section: "Verification and conditions" },
  "explain.title": { key: "explain.title", kind: "ExplanationCard", text: "Explain the {{subject}}", notes: "32.5 §3: one card per item; the prompt names the fact and asks one question.", extras: [], section: "Verification and conditions" },
  "explain.deposit.subject": { key: "explain.deposit.subject", kind: "ExplanationCard subject", text: "{{money}} deposit on {{date}}", notes: "32.5 §3/§4: a deposit above 50% of monthly qualifying income (22.4).", extras: [], section: "Verification and conditions" },
  "explain.inquiry.subject": { key: "explain.inquiry.subject", kind: "ExplanationCard subject", text: "{{creditor}} inquiry from {{date}}", notes: "32.5 §3: an inquiry within 90 days (22.2).", extras: [], section: "Verification and conditions" },
  "needs.doing.title": { key: "needs.doing.title", kind: "Record", text: "What we're doing", notes: "32.5 §1: `open` and `waiting_third_party` items with their owner label.", extras: [], section: "Verification and conditions" },
