  "new_debt.source": { key: "new_debt.source", kind: "ConfirmCard helper", text: "Source: the credit refresh we run before closing.", extras: ["*32.5 §2.4: names creditor, open date and source", "never a word about the decision.*"], section: "Verification and conditions" },
  "new_debt.rechecking": { key: "new_debt.rechecking", kind: "StatusCard", text: "Added. We're re-checking your application with the updated debt — we'll tell you if anything changes.", notes: "32.5 §2.4: after a yes the liability is added and DU is resubmitted per 23.1's tolerances.", extras: [], section: "Verification and conditions" },
  "human.agent.intro": { key: "human.agent.intro", kind: "PersonCard", text: "A person has your file and will pick up right here — with everything you've told us so far.", notes: "32.5 §8: `human.transfer.requested` → warm transfer with the full context; cards stay the only way to commit.", extras: [], section: "Verification and conditions" },
  "human.agent.pending": { key: "human.agent.pending", kind: "PersonCard name", text: "Your Supermortgage contact", notes: "32.5 §8: shown until the human's own turn carries their name.", extras: [], section: "Verification and conditions" },
  "needs.item.received": { key: "needs.item.received", kind: "receipt", text: "Got it — received and under review.", notes: "32.5 §2.2: the one-line confirmation when a document matches its request; the item is `satisfied_pending_review` until 23.3 clears it.", extras: [], section: "Verification and conditions" },
  "coborrower.joint_intent.first": { key: "coborrower.joint_intent.first", kind: "StatusCard", text: "First, one question only you can answer — then your own income, debts and profile.", notes: "32.5 §7: joint intent is captured before any credit is ordered for the invitee (`SM_O21_JOINT_INTENT_GATE`).", extras: [], section: "Verification and conditions" },
  "coborrower.deep_link": { key: "coborrower.deep_link", kind: "message", text: "You've been added to this application. Sign in with a code and we'll pick up right here: {{deep_link}}", notes: "32.5 §7: the invitee's own conversation and deep link.", extras: [], section: "Verification and conditions" },
  "conditions.checklist": { key: "conditions.checklist", kind: "ChecklistCard", text: "What's still needed to close", notes: "32.3 R8: materialized within SM_DU_CONDITIONS_SLA_4H; never DU text.", extras: ["helper: \"Items marked *you* are yours; the rest are ours or a third party's.\""], section: "Verification and conditions" },
  "thread.card_field_required": { key: "thread.card_field_required", kind: "reply", text: "Pick an answer for each item so it counts — nothing is submitted without your tap.", notes: "32.3 T13.", extras: [], section: "Verification and conditions" },
  "gate.demographics.application_first": { key: "gate.demographics.application_first", kind: "refusal", text: "Those questions come once your application is started.", notes: "20.3 T12 / 32.3 T15.", extras: [], section: "Verification and conditions" },
  "decision.counteroffer": { key: "decision.counteroffer", kind: "ChoiceCard", text: "We can offer these terms instead", extras: [], options: ["Accept these terms", "Decline", "Talk to a person"], section: "Decision, property, insurance, MI" },
  "decision.denial.next": { key: "decision.denial.next", kind: "line", text: "You can request a copy of the appraisal (if one was done) and reach a person any time.", extras: [], section: "Decision, property, insurance, MI" },
  "decision.noia": { key: "decision.noia", kind: "StatusCard", text: "We need the items in this notice by {{date}} to keep your application open.", extras: [], section: "Decision, property, insurance, MI" },
  "decision.withdraw.confirm": { key: "decision.withdraw.confirm", kind: "ChoiceCard", text: "This ends your application. Your documents stay available to you.", extras: [], options: ["Yes, withdraw", "Keep going"], section: "Decision, property, insurance, MI" },
  "valuation.value_acceptance": { key: "valuation.value_acceptance", kind: "StatusCard", text: "The underwriting system took your home's value as is. No appraisal, no fee.", extras: [], section: "Decision, property, insurance, MI" },
  "valuation.schedule": { key: "valuation.schedule", kind: "ScheduleCard", text: "Pick a time for the appraiser to visit (about an hour).", extras: [], section: "Decision, property, insurance, MI" },
