  "valuation.low.choice": { key: "valuation.low.choice", kind: "ChoiceCard", text: "The appraised value is {{money}}, below {{price|requested}}. Options:", notes: "32.6 §2: purchase levers; refinance: lower loan amount, add MI, stop.", extras: [], options: ["Renegotiate the price", "Bring the difference in cash", "Cancel under my contingency"], section: "Decision, property, insurance, MI" },
  "title.vesting.confirm": { key: "title.vesting.confirm", kind: "ConfirmCard", text: "Title will be held by {{names}} as {{vesting}}. Right?", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient": { key: "insurance.deficient", kind: "NoticeCard line", text: "One thing to fix: {{element}} — {{fix}}.", extras: [], section: "Decision, property, insurance, MI" },
  "flood.notice": { key: "flood.notice", kind: "DocumentCard", text: "Flood insurance is required for this property", extras: ["why: \"The property is in a special flood hazard area.\""], section: "Decision, property, insurance, MI" },
  "mi.compare.title": { key: "mi.compare.title", kind: "ComparisonCard", text: "Mortgage insurance options", extras: [], section: "Decision, property, insurance, MI" },
  "ctc.reached": { key: "ctc.reached", kind: "StatusCard", text: "Everything checks out. Next: your Closing Disclosure, then a signing time.", extras: [], section: "Decision, property, insurance, MI" },
  "ctc.final_review": { key: "ctc.final_review", kind: "StatusCard", text: "A final review is in progress — nothing needed from you.", extras: [], section: "Decision, property, insurance, MI" },
  "decision.approval.notice": { key: "decision.approval.notice", kind: "NoticeCard", text: "Your approval letter", notes: "32.6 §1.1: NTC_REGB_1002_9_APPROVAL rendered by 23.3; the conditions are the letter's borrower-facing list.", extras: ["line: \"Approved with conditions — good through {{valid_until}}. The letter lists what's still needed.\""], section: "Decision, property, insurance, MI" },
  "decision.counteroffer.notice": { key: "decision.counteroffer.notice", kind: "NoticeCard", text: "Our counteroffer", notes: "32.6 §1.2: NTC_REGB_1002_9_COUNTEROFFER; never \"you were declined\" while the offer is open.", extras: ["line: \"We can't offer the terms you asked for, but here's what we can offer. The notice explains why.\""], section: "Decision, property, insurance, MI" },
  "decision.counteroffer.compare": { key: "decision.counteroffer.compare", kind: "ComparisonCard", text: "What you asked for vs. what we can offer", notes: "32.6 §1.2: loan amount, rate, monthly principal & interest, loan-to-value; the offered column is recommended.", extras: [], section: "Decision, property, insurance, MI" },
  "decision.denial.notice": { key: "decision.denial.notice", kind: "NoticeCard", text: "Your decision letter", notes: "32.6 §1.3: NTC_REGB_1002_9_ADVERSE_ACTION; the Record goes read-only.", extras: ["line: \"The letter lists the specific reasons. Your documents stay available to you here.\""], section: "Decision, property, insurance, MI" },
  "decision.noia.notice": { key: "decision.noia.notice", kind: "NoticeCard", text: "What we still need", notes: "32.6 §1.4: NTC_REGB_1002_9_NOIA.", extras: ["line: \"The notice lists the items and the date we need them by.\""], section: "Decision, property, insurance, MI" },
  "valuation.handoff.appraiser": { key: "valuation.handoff.appraiser", kind: "HandoffCard", text: "The appraiser is coordinating the visit", notes: "32.6 §2.", extras: ["what_to_expect: \"On a purchase the appraiser arranges access with the listing side. Nothing needed from you.\""], section: "Decision, property, insurance, MI" },
  "valuation.copy.mailed": { key: "valuation.copy.mailed", kind: "StatusCard", text: "Your appraisal copy was mailed {{date}}.", notes: "32.6 §2: a mailed copy shows Mailed and no receipt action.", extras: [], section: "Decision, property, insurance, MI" },
  "hoa.docs.upload": { key: "hoa.docs.upload", kind: "UploadCard", text: "Send your association's {{document}}", notes: "SQ-08, owner you.", extras: ["why: \"Your HOA sends this to owners; we need it for the project review.\""], section: "Decision, property, insurance, MI" },
  "hoa.docs.handoff": { key: "hoa.docs.handoff", kind: "HandoffCard", text: "We're asking {{hoa_contact}} for the {{document}}", notes: "SQ-08, owner third party.", extras: ["what_to_expect: \"The management company sends it straight to us. Nothing needed from you.\""], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.deductible": { key: "insurance.deficient.element.deductible", kind: "token", text: "the deductible", notes: "32.6 §5: the failing element named on `insurance.deficient`.", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.deductible": { key: "insurance.deficient.fix.deductible", kind: "token", text: "a deductible no more than 5% of the coverage amount", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.coverage_form": { key: "insurance.deficient.element.coverage_form", kind: "token", text: "the coverage form", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.coverage_form": { key: "insurance.deficient.fix.coverage_form", kind: "token", text: "coverage on a replacement-cost basis for the required perils", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.carrier_rating": { key: "insurance.deficient.element.carrier_rating", kind: "token", text: "the carrier's rating", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.carrier_rating": { key: "insurance.deficient.fix.carrier_rating", kind: "token", text: "a carrier rated AM Best B or better (or the Demotech, S&P or Kroll equivalent)", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.mortgagee_clause": { key: "insurance.deficient.element.mortgagee_clause", kind: "token", text: "the mortgagee clause", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.mortgagee_clause": { key: "insurance.deficient.fix.mortgagee_clause", kind: "token", text: "the mortgagee clause exactly as it must read: {{partner.legal_name}}, its successors and/or assigns, c/o Supermortgage", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.effective_date": { key: "insurance.deficient.element.effective_date", kind: "token", text: "the effective date", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.effective_date": { key: "insurance.deficient.fix.effective_date", kind: "token", text: "a policy in force on or before your disbursement date, with the first year's premium paid", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.flood_coverage": { key: "insurance.deficient.element.flood_coverage", kind: "token", text: "the flood coverage", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.fix.flood_coverage": { key: "insurance.deficient.fix.flood_coverage", kind: "token", text: "flood coverage for the lesser of the loan amount, the NFIP maximum or the replacement cost, applied for and paid at or before closing", extras: [], section: "Decision, property, insurance, MI" },
  "insurance.deficient.element.coverage": { key: "insurance.deficient.element.coverage", kind: "token", text: "the coverage", extras: [], section: "Decision, property, insurance, MI" },
