  "insurance.upload.policy": { key: "insurance.upload.policy", kind: "UploadCard", text: "Send the corrected declarations page", notes: "32.6 §5: the item stays in Needed-from-you.", extras: ["why: \"Once your carrier fixes it, send the new page and we'll check it again.\""], section: "Decision, property, insurance, MI" },
  "mi.plan.bpmi_monthly": { key: "mi.plan.bpmi_monthly", kind: "column", text: "Borrower-paid monthly", extras: [], section: "Decision, property, insurance, MI" },
