  "mi.plan.lpmi": { key: "mi.plan.lpmi", kind: "column", text: "Lender-paid (higher rate)", extras: [], section: "Decision, property, insurance, MI" },
  "mi.cancel.bpmi_monthly": { key: "mi.cancel.bpmi_monthly", kind: "row", text: "You can ask to cancel at 80% of the original value; it ends automatically at 78%.", notes: "HPA §4902(a)/(b), one line.", extras: [], section: "Decision, property, insurance, MI" },
  "mi.cancel.single": { key: "mi.cancel.single", kind: "row", text: "Paid once up front, no monthly line; a refund follows the insurer's plan if the loan pays off early.", extras: [], section: "Decision, property, insurance, MI" },
  "mi.cancel.split": { key: "mi.cancel.split", kind: "row", text: "Part up front, part monthly; the monthly part ends the same way as monthly MI.", extras: [], section: "Decision, property, insurance, MI" },
  "mi.cancel.lpmi": { key: "mi.cancel.lpmi", kind: "row", text: "No separate MI line; the higher rate stays for the life of the loan and can't be cancelled.", notes: "HPA §4905(c).", extras: [], section: "Decision, property, insurance, MI" },
  "closing.schedule.waiting": { key: "closing.schedule.waiting", kind: "StatusCard", text: "Closing times open once your Closing Disclosure sets the earliest closing date.", notes: "32.6 §7 / 32.7 §2.", extras: [], section: "Decision, property, insurance, MI" },
  "cd.delivered": { key: "cd.delivered", kind: "DocumentCard", text: "Your Closing Disclosure", extras: ["why: \"Confirming receipt starts the 3-business-day wait before you can sign. Sundays and federal holidays don't count.\""], section: "Closing, rescission, funding, boarding" },
  "cd.mailbox": { key: "cd.mailbox", kind: "StatusCard", text: "Mailed {{date}}; it counts as received on {{date}} unless you confirm sooner.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.redisclosed_restart": { key: "cd.redisclosed_restart", kind: "StatusCard", text: "This change restarts the three-day wait. Earliest closing is now {{date}}.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.wire_warning": { key: "cd.wire_warning", kind: "line", text: "Never send closing funds from instructions received by e-mail. Confirm by phone with your settlement agent first.", extras: [], section: "Closing, rescission, funding, boarding" },
  "closing.schedule": { key: "closing.schedule", kind: "ScheduleCard", text: "Pick your signing time", extras: ["helper: \"{{closing_type_sentence}} About 15–20 minutes. Have your ID ready.\""], section: "Closing, rescission, funding, boarding" },
  "closing.presign": { key: "closing.presign", kind: "HandoffCard", text: "You can pre-sign the non-notarized documents now. The rest is signed live with the notary.", extras: [], section: "Closing, rescission, funding, boarding" },
  "closing.failed": { key: "closing.failed", kind: "StatusCard", text: "The session couldn't be completed. Let's pick a new time, or sign on paper with the settlement agent.", extras: [], section: "Closing, rescission, funding, boarding" },
