  "signed.purchase": { key: "signed.purchase", kind: "StatusCard", text: "Signed. Funds go out {{when}}.", extras: [], section: "Closing, rescission, funding, boarding" },
  "rescission.how": { key: "rescission.how", kind: "link", text: "How to cancel", extras: [], section: "Closing, rescission, funding, boarding" },
  "rescission.confirm": { key: "rescission.confirm", kind: "ChoiceCard", text: "Cancelling ends this loan. Anything you paid is returned within 20 days.", extras: [], options: ["Yes, cancel", "Keep my loan"], section: "Closing, rescission, funding, boarding" },
  "rescission.expired": { key: "rescission.expired", kind: "StatusCard", text: "Your cancel window ended. Funding is scheduled for {{date}}.", extras: [], section: "Closing, rescission, funding, boarding" },
