  "funded.refi": { key: "funded.refi", kind: "StatusCard", text: "Funded. {{prior_servicer}} is being paid off today; they refund your old escrow balance within 20 days — watch for it. Your first payment of {{money}} is due {{date}}.", extras: [], section: "Closing, rescission, funding, boarding" },
  "funded.purchase": { key: "funded.purchase", kind: "StatusCard", text: "Funded. Ownership is being recorded; keys through your settlement agent. First payment {{money}} on {{date}}.", extras: [], section: "Closing, rescission, funding, boarding" },
  "funded.no_skip": { key: "funded.no_skip", kind: "line", text: "Interest from {{disbursement}} to {{month_end}} was collected at closing — no payment is skipped.", extras: [], section: "Closing, rescission, funding, boarding" },
  "boarding.welcome": { key: "boarding.welcome", kind: "StatusCard", text: "Welcome. You pay Supermortgage, servicing on behalf of {{partner.legal_name}}. Set up autopay and e-statements below.", extras: [], section: "Closing, rescission, funding, boarding" },
  "boarding.fannie_letter": { key: "boarding.fannie_letter", kind: "HandoffCard", text: "Within about a month you'll get a letter from Fannie Mae saying it owns your loan. Nothing changes — you still pay Supermortgage.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.preparing": { key: "cd.preparing", kind: "StatusCard", text: "Preparing your Closing Disclosure.", notes: "32.7 §1: `drafting`/`gated`; Next shows `SM_O62_CD_TARGET_4SBD.due_at`.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.what_changed": { key: "cd.what_changed", kind: "block title", text: "What changed since your Loan Estimate", notes: "32.7 §1: the LE→CD row diff from the two figure snapshots; tolerance cures shown as lender credits.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.row.apr": { key: "cd.row.apr", kind: "What-changed row", text: "APR", notes: "32.7 §1.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.row.lender_credit": { key: "cd.row.lender_credit", kind: "What-changed row", text: "Lender credits", notes: "32.7 §1.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.row.payoff": { key: "cd.row.payoff", kind: "What-changed row", text: "Payoff of your current loan", notes: "32.7 §1: refinance.", extras: [], section: "Closing, rescission, funding, boarding" },
  "cd.row.escrow": { key: "cd.row.escrow", kind: "What-changed row", text: "Monthly escrow", notes: "32.7 §1: refinance.", extras: [], section: "Closing, rescission, funding, boarding" },
