  "cd.corrected": { key: "cd.corrected", kind: "DocumentCard", text: "Your updated Closing Disclosure", notes: "32.7 §1 `superseded`; `cd.redisclosed_restart` follows when the three-day wait restarts (T2).", extras: ["why: \"Compare it with the earlier version — what changed is listed below. Confirming receipt keeps your closing on track.\""], section: "Closing, rescission, funding, boarding" },
  "cd.corrected.post": { key: "cd.corrected.post", kind: "DocumentCard", text: "A corrected Closing Disclosure", notes: "32.7 §1: `corrected_post_consummation`, requires_ack=false.", extras: ["why: \"We corrected a figure after closing. Nothing to do — this is for your records.\""], section: "Closing, rescission, funding, boarding" },
