  "closing.schedule.type.ipen": { key: "closing.schedule.type.ipen", kind: "line", text: "In person with the settlement agent. You sign on a screen.", notes: "32.7 §2.", extras: [], section: "Closing, rescission, funding, boarding" },
  "closing.schedule.type.hybrid": { key: "closing.schedule.type.hybrid", kind: "line", text: "In person. You sign a paper note; the rest is on a screen.", notes: "32.7 §2.", extras: [], section: "Closing, rescission, funding, boarding" },
