  "auth.link_loan": { key: "auth.link_loan", kind: "ConfirmCard", text: "Already have a loan with us? Link it with a few facts only you would know.", notes: "DELTA-16, phase 3: `party.linkLoan`; a mismatch never says which field.", extras: ["fields: last 4 of your loan number or the property ZIP · last 4 of your SSN · date of birth"], section: "Entry, sign-up and sign-in (32.14)" },
  "consent.credit.soft.title": { key: "consent.credit.soft.title", kind: "ConsentCard", text: "Check my credit with a soft pull", notes: "S4: `credit.authorize{kind: soft_pull, consumer_entered_identity: true}` at L1 (DELTA-13).", extras: ["helper: \"A soft pull doesn't affect your score. A full credit check happens only if you apply.\""], section: "Entry, sign-up and sign-in (32.14)" },
  "consent.credit.soft.body": { key: "consent.credit.soft.body", kind: "ConsentCard body", text: "I authorize {{partner.legal_name}} to obtain my credit report to prequalify me. This is a soft inquiry and does not affect my credit score. A full credit check happens only if I choose to apply.", notes: "S4: `requires_typed_name: true`.", extras: ["footer: \"Type your name to authorize.\""], section: "Entry, sign-up and sign-in (32.14)" },
  "credit.freeze.lift": { key: "credit.freeze.lift", kind: "StatusCard", text: "Your credit file is frozen, so the bureau couldn't share it. Lift the freeze with the bureau, then tap Try again. Nothing else changes.", notes: "S4: a freeze is not a decline; no adverse inference.", extras: [], section: "Entry, sign-up and sign-in (32.14)" },
  "deep_link.unknown": { key: "deep_link.unknown", kind: "refusal", text: "That link doesn't work. Sign in and we'll find your place.", notes: "S5: `GET /v1/borrower/deeplink/{token}` answers 404.", extras: [], options: ["Sign in"], section: "Entry, sign-up and sign-in (32.14)" },
  "deep_link.expired": { key: "deep_link.expired", kind: "refusal", text: "That link has expired. Sign in and we'll take you there.", notes: "S5: 410.", extras: [], options: ["Sign in"], section: "Entry, sign-up and sign-in (32.14)" },
  "entry.step.continue": { key: "entry.step.continue", kind: "button", text: "Continue", notes: "S1: the one submit for the state select and the two estimate fields (chips resolve on tap; a select or typed field needs an explicit submit for keyboard users, WCAG 3.2.2).", extras: [], section: "Entry, sign-up and sign-in (32.14)" },
